// ==UserScript==
// @name         Endorse Button
// @namespace    http://tampermonkey.net/
// @version      0.3
// @description  Makes endotarting easier
// @author       Atlae
// @match        https://www.nationstates.net/nation=*
// @icon         https://www.google.com/s2/favicons?domain=nationstates.net
// @require      https://craig.global.ssl.fastly.net/js/mousetrap/mousetrap.min.js?a4098
// @grant        window.close
// ==/UserScript==

/*
 * Keybinds
 * [e]ndorse
 * [w] to close
 * [r]eload
 */

(function() {
    'use strict';

    Mousetrap.bind('e', function(ev) {
        if (document.getElementsByClassName("endorse button icon wa").length == 1 && document.getElementsByClassName("endorse button icon wa")[0].innerText != 'Withdraw Your Endorsement') {
            document.getElementsByClassName("endorse button icon wa")[0].click()
        }
    });
    Mousetrap.bind('w', function(ev) { window.close() });
    Mousetrap.bind('r', function(ev) { window.location.reload() });
})();
```
